const casinoRoom=()=>Math.max(0,Math.min(S.cash,S.casino.budget-S.casino.spent));
function quickValue(spec){const [kind,a,b]=spec.split(':');
 if(kind==='abs')return nice(Number(a));
 if(kind==='cash')return nice(S.cash*Number(a));
 if(kind==='hold')return nice((S.holdings[a]||0)*S.market[a].price*Number(b));
 if(kind==='room')return nice(casinoRoom()*Number(a));
 return 1;}
