function defaults(){return {v:2,life:freshLife(),cash:0,earned:0,clicks:0,path:'culinary',careers:Object.fromEntries(PATHS.map(p=>[p.id,{rank:0,xp:0,courses:0,spec:'',contracts:0}])),business:{},properties:{},items:{},hobbies:{},holdings:{},market:Object.fromEntries(FUNDS.map(f=>[f.id,{price:f.price,hist:[f.price],basis:0}])),marketClock:0,marketDays:0,training:null,leisure:null,contract:null,claims:{},log:[],legacy:0,generation:1,lifetime:0,archiveValue:0,archiveIncome:0,auto:true,last:Date.now(),tab:'work',careerView:'culinary',businessFilter:'all',casino:{budget:0,spent:0,plays:0,won:0,lost:0,game:'roulette',hand:null,result:'Choose a table and set a session budget.',symbols:['★','◆','♣'],roulette:null},settings:{motion:true},migration:false,house:freshHouse(),people:freshPeople()};}
