function normalize(raw){
 if(!raw||typeof raw!=='object'||raw.v!==2)throw Error('This is not a Clock Out version 2 save.');
 const d=defaults();
 for(const k of ['cash','earned','clicks','legacy','lifetime','archiveValue','archiveIncome','marketDays'])d[k]=num(raw[k]);
 d.generation=Math.max(1,Math.floor(num(raw.generation,1e6)));d.last=num(raw.last,Date.now())||Date.now();
 d.path=PATHS.some(p=>p.id===raw.path)?raw.path:'culinary';d.careerView=PATHS.some(p=>p.id===raw.careerView)?raw.careerView:d.path;
 d.tab=NAV.some(n=>n.id===raw.tab)?raw.tab:'work';d.auto=raw.auto!==false;d.migration=!!raw.migration;d.settings.motion=raw.settings?.motion!==false;
 PATHS.forEach(p=>{const c=raw.careers?.[p.id]||{};d.careers[p.id]={rank:Math.floor(num(c.rank,4)),xp:num(c.xp,1e9),courses:Math.floor(num(c.courses,4)),contracts:Math.floor(num(c.contracts,1e6)),spec:p.specs.some(x=>x[0]===c.spec)?c.spec:''};});
 BUSINESSES.forEach(b=>{const q=raw.business?.[b.id];if(q&&q.level>0)d.business[b.id]={level:Math.max(1,Math.floor(num(q.level,25))),staff:Math.floor(num(q.staff,10)),equipment:Math.floor(num(q.equipment,10)),strategy:['steady','premium','volume'].includes(q.strategy)?q.strategy:'steady'};});
 PROPERTIES.forEach(p=>{if(raw.properties?.[p.id])d.properties[p.id]={renovation:Math.floor(num(raw.properties[p.id].renovation,5))};});
 ITEMS.forEach(i=>{if(raw.items?.[i.id]===true)d.items[i.id]=true;});HOBBIES.forEach(h=>{d.hobbies[h.id]=Math.floor(num(raw.hobbies?.[h.id],10));});
 FUNDS.forEach(f=>{const m=raw.market?.[f.id]||{};d.market[f.id]={price:f.id==='savings'?1:clamp(num(m.price)||f.price,.1,1e8),basis:num(m.basis),hist:Array.isArray(m.hist)?m.hist.slice(-40).map(x=>clamp(num(x),.1,1e8)):[f.price]};d.holdings[f.id]=num(raw.holdings?.[f.id]);});
 d.marketClock=num(raw.marketClock,59.99);
 if(raw.training&&PATHS.some(p=>p.id===raw.training.path)&&raw.training.tier===d.careers[raw.training.path].courses&&raw.training.tier<4)d.training={path:raw.training.path,tier:raw.training.tier,remaining:num(raw.training.remaining,3600)};
 if(raw.leisure&&HOBBIES.some(h=>h.id===raw.leisure.id))d.leisure={id:raw.leisure.id,remaining:num(raw.leisure.remaining,3600)};
 if(raw.contract&&PATHS.some(p=>p.id===raw.contract.path))d.contract={path:raw.contract.path,progress:num(raw.contract.progress,500),target:clamp(num(raw.contract.target),1,500),reward:num(raw.contract.reward,1e9)};
 GOALS.forEach(g=>{if(raw.claims?.[g.id]===true)d.claims[g.id]=true;});
 d.log=Array.isArray(raw.log)?raw.log.slice(0,30).filter(x=>typeof x==='string').map(x=>x.slice(0,200)):[];
 const c=raw.casino||{};for(const k of ['budget','spent','plays','won','lost'])d.casino[k]=num(c[k]);d.casino.spent=Math.min(d.casino.spent,d.casino.budget);d.casino.game=['roulette','slots','coin','blackjack'].includes(c.game)?c.game:'roulette';
 // Hands are persisted so a reload cannot erase a losing hand or refund a stake.
 if(c.hand&&c.hand.live===true){const h=c.hand,cardOk=v=>Number.isInteger(v)&&v>=0&&v<52;if(Array.isArray(h.deck)&&h.deck.length<=104&&h.deck.every(cardOk)&&Array.isArray(h.p)&&h.p.length>=2&&h.p.length<15&&h.p.every(cardOk)&&Array.isArray(h.d)&&h.d.length>=2&&h.d.length<15&&h.d.every(cardOk)&&num(h.bet)>0)d.casino.hand={deck:h.deck,p:h.p,d:h.d,bet:num(h.bet),live:true};}
 if(d.casino.hand?.live)d.casino.result='Your saved hand is waiting. Hit, stand, or double.';
 normalizeLife(raw.life,d);normalizeHouse(raw.house,d);normalizePeople(raw.people,d);return d;
}
const NAV=[{id:'work',name:'Work',icon:'▣',group:'YOUR EVERYDAY'},{id:'careers',name:'Careers',icon:'↗'},{id:'school',name:'Education',icon:'▤'},{id:'life',name:'Your life',icon:'⌂'},{id:'city',name:'The city',icon:'▦',group:'A BIGGER WORLD'},{id:'business',name:'Businesses',icon:'▥'},{id:'invest',name:'Investments',icon:'◴'},{id:'casino',name:'The Velvet Room',icon:'♠'},{id:'journal',name:'Milestones',icon:'☆',group:'YOUR STORY'},{id:'settings',name:'Save & settings',icon:'⚙'}];
function migrate(old){
 const d=defaults();d.migration=true;d.cash=num(old.cash);d.earned=num(old.earned);d.clicks=num(old.clicks);d.legacy=num(old.legacy,1000000);d.generation=Math.max(1,num(old.gens));d.lifetime=num(old.lifetime?.earned)||d.earned;d.last=num(old.last,Date.now())||Date.now();
 const jobs={fry:['culinary',0],cashier:['culinary',0],barista:['culinary',1],delivery:['trades',0],temp:['finance',0],sales:['finance',1],jrdev:['tech',1],accountant:['finance',2],engineer:['tech',2],lawyer:['finance',3],doctor:['medicine',3],director:['finance',3],vp:['finance',4],ceo:['finance',4],hedge:['finance',4],mogul:['finance',4]};
 for(const [id,count] of Object.entries(old.jobClicks||{})){const [path,rank]=jobs[id]||['culinary',0];const c=d.careers[path];c.rank=Math.max(c.rank,rank);c.xp+=num(count,1e9);c.courses=Math.max(c.courses,rank);}
 const [path,rank]=jobs[old.job]||['culinary',0];d.path=path;d.careerView=path;d.careers[path].rank=Math.max(d.careers[path].rank,rank);d.careers[path].courses=Math.max(d.careers[path].courses,rank);d.careers[path].xp=Math.max(d.careers[path].xp,XP_REQ[rank]);
 ITEMS.forEach(i=>{if(old.assets?.[i.id])d.items[i.id]=true;});
 // Unsupported holdings become a clearly labeled, income-bearing legacy trust.
 const legacyH=[['lemonade',60,.6],['dogs',350,3.5],['delivery',1800,16],['etsy',9000,70],['youtube',45000,320],['dropship',220000,1400],['podcast',1.2e6,6500],['appstudio',7e6,35000]];
 const legacyB=[['truck',30000,180],['laundro',150000,800],['carwash',600000,3000],['restaurant',2.5e6,11000],['franchise',12e6,48000],['startup',60e6,220000],['bank',400e6,1.3e6],['space',3e9,9e6]];
 for(const [list,owned] of [[legacyH,old.hustles],[legacyB,old.biz]])for(const [id,cost,rate] of list){const n=Math.floor(num(owned?.[id],100000));d.archiveValue+=Math.min(1e30,cost*(1.15**Math.min(n,490)-1)/.15*.5);d.archiveIncome+=num(rate*n*2**[10,25,50,100,200,500,1000].filter(t=>n>=t).length);}
 const oldIdleEducation={bachelors:.1,mba:.25,phd:.5},oldIdleAssets={phone:.05,apartment:.1,house:.2,penthouse:.25,yacht:.3,jet:.5,island:1};
 const idleBoost=1+Object.entries(oldIdleEducation).reduce((n,[id,v])=>n+(old.edu?.[id]?v:0),0)+Object.entries(oldIdleAssets).reduce((n,[id,v])=>n+(old.assets?.[id]?v:0),0);d.archiveIncome*=idleBoost*(1+.1*d.legacy);
 const oldQualifications={ged:[['finance',1]],college:[['finance',2],['creative',1]],bootcamp:[['tech',2]],bachelors:[['tech',3],['finance',3]],mba:[['finance',4]],law:[['finance',4]],med:[['medicine',4]],phd:[['tech',4]]};
 for(const [id,qualifications] of Object.entries(oldQualifications))if(old.edu?.[id])for(const [p,t] of qualifications)d.careers[p].courses=Math.max(d.careers[p].courses,t);
 const oldItemCosts={bike:250,phone:900,car:6000,apartment:60000,assistant:25000,house:750000,team:2e6};for(const i of ITEMS)if(d.items[i.id]&&oldItemCosts[i.id])d.archiveValue+=Math.max(0,oldItemCosts[i.id]-i.cost);
 for(const v of Object.values(old.invest||{}))d.holdings.savings=(d.holdings.savings||0)+num(v?.bal);d.market.savings.basis=d.holdings.savings||0;
 const extraAssets={sportscar:150000,penthouse:5e6,yacht:30e6,jet:150e6,clones:2e8,island:2e9};for(const [id,cost]of Object.entries(extraAssets))if(old.assets?.[id])d.archiveValue+=cost;
 const oldPay={fry:7.25,cashier:9.5,barista:12,delivery:16,temp:20,sales:32,jrdev:48,accountant:65,engineer:120,lawyer:260,doctor:420,director:700,vp:1500,ceo:4000,hedge:12000,mogul:60000};
 const eduClick={ged:.1,college:.15,bootcamp:.2,bachelors:.3,mba:.5,law:.5,med:.6,phd:.3},assetClick={bike:.05,car:.1,sportscar:.2,penthouse:.25,yacht:.3,jet:.5,island:1};
 const oldClickBoost=1+Object.entries(eduClick).reduce((n,[id,v])=>n+(old.edu?.[id]?v:0),0)+Object.entries(assetClick).reduce((n,[id,v])=>n+(old.assets?.[id]?v:0),0);
 const oldAuto=(old.assets?.assistant?1:0)+(old.assets?.team?5:0)+(old.assets?.clones?30:0),oldLevel=Math.min(10,Math.floor(Math.sqrt(num(old.jobClicks?.[old.job])/20)));
 d.archiveIncome+=Math.max(0,oldAuto*(oldPay[old.job]||7.25)*(1+.15*oldLevel)*oldClickBoost*(1+.1*d.legacy)-automatic(d)*clickPay(d));
 for(const k of ['won','lost','plays'])d.casino[k]=num(old.casino?.[k]);
 d.log=['Your Grind save was imported. Original save retained. Existing businesses are held in the legacy trust; investment balances moved to the cash reserve.'];return normalize(d);
}
function load(){try{const raw=localStorage.getItem(KEY);if(raw)S=normalize(JSON.parse(raw));else{const old=localStorage.getItem('grind.v1');if(old)S=migrate(JSON.parse(old));}}catch(e){paused=true;loadError='Your saved data could not be read. Nothing has been overwritten. Use Save & settings to import a backup or download the unreadable save.';}}
let loadError='';
function save(){if(paused)return false;S.last=Date.now();try{localStorage.setItem(KEY,JSON.stringify(S));try{localStorage.setItem('clockout.leaderboard.snapshot.v1',JSON.stringify({version:1,netWorth:Math.max(0,netWorth()),generation:S.generation,savedAt:S.last}));}catch{};if(typeof document!=='undefined')$('#save-status').textContent='● SAVED LOCALLY';return true;}catch(e){if(typeof document!=='undefined')$('#save-status').textContent='SAVE FAILED — EXPORT BACKUP';return false;}}
const career=(s=S)=>s.careers[s.path];
function comfort(s=S){return Math.max(0,lifeComfort(s)+ITEMS.reduce((n,i)=>n+(i.kind==='comfort'&&s.items[i.id]?i.bonus:0),0)+Object.values(s.hobbies).reduce((a,b)=>a+b,0)*.5+houseComfort(s));}
function clickPay(s=S){const c=career(s),p=PATH(s.path);return p.pay[c.rank]*(1+vehicleBoost(s)+ITEMS.reduce((n,i)=>n+(i.kind==='work'&&s.items[i.id]?i.bonus:0),0)+comfort(s)*.015)*(1+.1*s.legacy)*(c.spec===p.specs[0][0]?1.25:1)*(1+Math.min(.3,Math.floor(c.xp/100)*.01))*wellMult(s);}
function automatic(s=S){if(s.house&&(onLeave(s)||resting(s)))return 0;return s.auto?(s.clicks>=30?.1:0)+ITEMS.reduce((n,i)=>n+(i.kind==='auto'&&s.items[i.id]?i.bonus:0),0):0;}
function businessDetail(b,s=S){const q=s.business[b.id];if(!q)return {gross:0,costs:0,net:0};const c=s.careers[b.path],p=PATH(b.path),strategy=q.strategy==='premium'?1.15:q.strategy==='volume'?1.28:1;const synergy=1+c.rank*.06+(c.spec===p.specs[1][0]?.25:0);const gross=b.rate*q.level*(1+q.equipment*.2)*(1+q.staff*.12)*strategy*synergy*(1+s.legacy*.1)*(s.items.phone?1.05:1)*bizCondMult(b,s);const overhead=q.strategy==='volume'?.28:q.strategy==='premium'?.21:.12;return {gross,costs:gross*overhead,net:gross*(1-overhead)};}
function propertyRate(s=S){return PROPERTIES.reduce((a,p)=>a+(s.properties[p.id]?p.rate*(1+s.properties[p.id].renovation*.25)*.85:0),0);}
function incomeRate(s=S){return BUSINESSES.reduce((a,b)=>a+businessDetail(b,s).net,0)+propertyRate(s)+automatic(s)*clickPay(s)+s.archiveIncome;}
function portfolioValue(s=S){return FUNDS.reduce((n,f)=>n+(s.holdings[f.id]||0)*s.market[f.id].price,0);}
function netWorth(s=S){return -debtTotal(s)-(s.house?.arrears||0)+lifeWorth(s)+s.cash+portfolioValue(s)+s.archiveValue+BUSINESSES.reduce((n,b)=>n+(s.business[b.id]?b.cost*s.business[b.id].level:0),0)+ITEMS.reduce((n,i)=>n+(s.items[i.id]?i.cost:0),0)+PROPERTIES.reduce((n,p)=>n+(s.properties[p.id]?p.cost:0),0);}
function earn(n){if(!Number.isFinite(n)||n<0)return;S.cash=num(S.cash+n);S.earned=num(S.earned+n);S.lifetime=num(S.lifetime+n);}
function spend(n){if(paused||!Number.isFinite(n)||n<=0||S.cash+1e-7<n)return false;S.cash=Math.max(0,S.cash-n);return true;}
function note(msg){S.log.unshift(msg);S.log=S.log.slice(0,30);if(typeof document!=='undefined')toast(msg);}
function nextGoal(){return GOALS.find(g=>!S.claims[g.id]);}
function chapter(){return career().rank>=4?'06 / CLOCK OUT':S.items.house?'05 / ROOM TO GROW':Object.values(S.business).some(b=>b.level>=3)?'04 / BUILD SOMETHING':S.items.apartment?'03 / YOUR OWN KEYS':career().rank>=1?'02 / BREATHING ROOM':'01 / FIRST SHIFT';}
function startCourse(path){const c=S.careers[path];if(!PATHS.some(p=>p.id===path)||S.training||c.courses>=4||!spend(COURSE_COST[c.courses]))return false;const tier=c.courses;S.training={path,tier,remaining:COURSE_TIME[tier]*(S.items.desk?0.85:1)};note(`Started ${PATH(path).courses[tier]}.`);return true;}
function promote(path){const c=S.careers[path];if(!PATHS.some(p=>p.id===path)||c.rank>=4||c.xp<XP_REQ[c.rank+1]||c.courses<c.rank+1||paused)return false;c.rank++;note(`Promoted to ${PATH(path).roles[c.rank]}!`);return true;}
function switchCareer(path){if(!PATHS.some(p=>p.id===path)||paused||(S.clicks<10&&path!=='culinary'))return false;S.path=path;S.careerView=path;note(`Now working in ${PATH(path).name}. All career progress is kept.`);return true;}
function specialize(path,id){const c=S.careers[path];if(!PATHS.some(p=>p.id===path)||c.rank<2||c.spec||paused||!PATH(path).specs.some(x=>x[0]===id))return false;c.spec=id;note(`${PATH(path).name}: ${PATH(path).specs.find(x=>x[0]===id)[1]} specialization selected.`);return true;}
function contractStart(){if(S.contract||career().rank<1||paused)return false;const n=career().contracts;S.contract={path:S.path,progress:0,target:Math.min(160,25+n*5),reward:PATH(S.path).pay[career().rank]*(40+Math.min(n,30)*4)};return true;}
function workAction(){if(paused)return false;const pay=clickPay();earn(pay);S.clicks++;houseWork(pay);career().xp+=1+comfort()*.02;if(S.contract&&S.contract.path===S.path){S.contract.progress++;if(S.contract.progress>=S.contract.target){const reward=S.contract.reward;career().contracts++;career().xp+=20;S.contract=null;earn(reward);note(`Contract delivered. ${money(reward)} earned and +20 career XP.`);renderNeeded=true;}}if(S.clicks===10||S.clicks===30)renderNeeded=true;return pay;}
function buyItem(id){const i=ITEMS.find(x=>x.id===id);if(!i||S.items[id]||!spend(i.cost))return false;S.items[id]=true;note(`${i.name} is now part of your life.`);return true;}
function businessCost(b,q){return Math.ceil(b.cost*1.45**(q?.level||0));}
function businessBuy(id){const b=BUSINESSES.find(x=>x.id===id),q=S.business[id];if(!b||(q?.level||0)>=25||!spend(businessCost(b,q)))return false;if(!q){S.business[id]={level:1,staff:0,equipment:0,strategy:'steady'};H().cond.biz[id]=100;}else q.level++;note(`${b.name}: level ${S.business[id].level}.`);return true;}
function improveBusiness(id,kind){const b=BUSINESSES.find(x=>x.id===id),q=S.business[id];if(!b||!q||!['staff','equipment'].includes(kind)||q[kind]>=10||!spend(Math.ceil(b.cost*.35*1.7**q[kind])))return false;q[kind]++;return true;}
function buyProperty(id){const p=PROPERTIES.find(x=>x.id===id);if(!p||S.properties[id]||!spend(p.cost))return false;S.properties[id]={renovation:0};note(`You own ${p.name.toLowerCase()}.`);return true;}
function renovate(id){const p=PROPERTIES.find(x=>x.id===id),q=S.properties[id];if(!p||!q||q.renovation>=5||!spend(p.cost*.25*1.7**q.renovation))return false;q.renovation++;return true;}
function startHobby(id){const h=HOBBIES.find(x=>x.id===id),l=S.hobbies[id]||0;if(!h||S.leisure||l>=10||!spend(100*2**l))return false;S.leisure={id,remaining:45+l*20};return true;}
function trade(id,amount,sell=false){const f=FUNDS.find(x=>x.id===id);if(!f||!Number.isFinite(amount)||amount<=0||paused)return false;const m=S.market[id],owned=S.holdings[id]||0;if(sell){const units=Math.min(owned,amount/m.price);if(!units)return false;S.holdings[id]=Math.max(0,owned-units);m.basis=owned>0?m.basis*(S.holdings[id]/owned):0;S.cash=num(S.cash+units*m.price);}else{if(!spend(amount))return false;S.holdings[id]=owned+amount/m.price;m.basis+=amount;}return true;}
function rebalance(amounts){const total=amounts.reduce((a,b)=>a+b,0);if(amounts.length!==FUNDS.length||amounts.some(n=>!Number.isFinite(n)||n<0)||Math.abs(total-100)>.001||paused)return false;const value=portfolioValue();if(value<=0)return false;FUNDS.forEach((f,i)=>{S.holdings[f.id]=value*amounts[i]/100/S.market[f.id].price;S.market[f.id].basis=value*amounts[i]/100;});note('Portfolio rebalanced. Cost basis starts at this allocation.');return true;}
function marketDay(random=Math.random){S.marketDays++;FUNDS.forEach(f=>{const m=S.market[f.id];if(f.id==='savings'){earn((S.holdings[f.id]||0)*f.drift);}else{const shock=(random()-.5)*2;const cycle=Math.sin(S.marketDays/14)*f.vol*.12;m.price=clamp(m.price*(1+f.drift+shock*f.vol+cycle),.1,1e8);}m.hist.push(m.price);if(m.hist.length>40)m.hist.shift();});if(typeof document!=='undefined'&&S.tab==='invest'){document.querySelectorAll('.market-chart[data-fund]').forEach(el=>{const fund=FUNDS.find(f=>f.id===el.dataset.fund);if(fund)el.outerHTML=spark(fund);});}}
function advance(seconds,away=false,random=Math.random){
 if(paused||!Number.isFinite(seconds)||seconds<=0)return 0;seconds=Math.min(seconds,MAX_OFFLINE);const gained=incomeRate()*seconds;earn(gained);const beforeXP=career().xp;career().xp+=automatic()*seconds*.3;if(career().rank<4&&beforeXP<XP_REQ[career().rank+1]&&career().xp>=XP_REQ[career().rank+1])renderNeeded=true;
 for(const key of ['training','leisure']){const task=S[key];if(!task)continue;task.remaining=Math.max(0,task.remaining-seconds);if(task.remaining===0){if(key==='training'){S.careers[task.path].courses=Math.max(S.careers[task.path].courses,task.tier+1);S.careers[task.path].xp+=25;note(`Completed ${PATH(task.path).courses[task.tier]}.`);}else{const h=HOBBIES.find(x=>x.id===task.id);S.hobbies[task.id]=Math.min(10,(S.hobbies[task.id]||0)+1);S.careers[h.skill].xp+=15;note(`${h.name} reached level ${S.hobbies[task.id]}.`);}S[key]=null;renderNeeded=true;}}
 // Risk assets stay flat while away; the stable cash reserve earns simple interest.
 if(away){earn((S.holdings.savings||0)*FUNDS[0].drift*seconds/60);}else{S.marketClock+=seconds;while(S.marketClock>=60){S.marketClock-=60;marketDay(random);}}
 houseAdvance(seconds,away,gained);
 return gained;
}
// ===================== LIFE HAS CONSEQUENCES =====================
// Household budget, health & stress, debt, maintenance, setbacks and recovery.
// Clock: 1 game day = 60 s of ACTIVE play (S.house.day); 1 game week = 7 game days.
// Nothing in this module advances while the game is closed. Away time only settles
// household costs out of away earnings, never from savings (see houseAdvance).
// Extension points: EVENTS (new setbacks), LOANS (new credit products), SPEND (tiers).
const DAY=60, WEEK=7;
const SPEND={
 modest:{name:'Modest',food:.06,extra:0,minExtra:0,comfort:0,recover:1,desc:'Cook at home, walk more, keep it simple. No comfort bonus, cheapest to sustain.'},
 comfortable:{name:'Comfortable',food:.12,extra:.01,minExtra:.05,comfort:2,recover:1.25,desc:'Small treats and the odd night out. +2 comfort and 25% faster stress recovery.'},
 luxurious:{name:'Luxurious',food:.30,extra:.05,minExtra:.5,comfort:5,recover:1.5,desc:'Fine dining, travel, the good stuff. +5 comfort, 50% faster recovery. Lifestyle spending scales with income.'}};
const LOANS={
 emergency:{name:'Emergency loan',rate:.02,weeks:8,down:0,desc:'Unsecured. Missed payments add fees. Four misses send it to collections: 15% of work pay goes to the lender until it is repaid.'},
 vehicle:{name:'Vehicle financing',rate:.008,weeks:26,down:.2,desc:'Secured by the vehicle. Four missed payments trigger a repossession review, where you choose to catch up, restructure, or surrender the vehicle.'},
 home:{name:'Home financing',rate:.004,weeks:52,down:.2,desc:'Secured by the home. Four missed payments trigger a foreclosure review, where you choose to catch up, restructure, or surrender the home.'}};
const HR={roomRent:.12,utilBase:.05,utilPerComfort:.01,homeFees:.000012,homeUpkeep:.000008,homeOther:.000004,carRun:.00003,bikeRun:.01,carStored:.000003,plan:.00001,
 decay:{home:.25,homeOther:.06,car:.4,carStored:.04,biz:.3},repair:{home:.06,car:.06,biz:.05},sale:{home:.8,car:.75},forced:{home:.7,car:.6}};
let manualActions=0;
function freshHouse(){return {v:1,day:0,dayClock:0,spend:'comfortable',health:85,stress:15,arrears:0,arrearsSince:-1,loans:[],cond:{homes:{},cars:{},biz:{}},plans:{homes:{},cars:{},biz:{}},grace:0,load:0,cooldown:0,pending:null,fx:{restUntil:0,pushUntil:0,leaveUntil:0,slow:{},transit:false,collections:false,burnoutSeen:false,deferred:false,restDay:-9},lastFire:{},away:null,loanSeq:0,cut:false};}
function normalizeHouse(raw,d){
 const h=freshHouse();
 if(!raw||typeof raw!=='object'){if(d.clicks>0||d.cash>0||Object.keys(d.business).length||d.generation>1)h.grace=14;d.house=h;return h;}
 h.day=num(raw.day);h.dayClock=clamp(num(raw.dayClock),0,DAY);h.spend=SPEND[raw.spend]?raw.spend:'comfortable';
 h.health=Number.isFinite(raw.health)?clamp(raw.health,0,100):85;h.stress=Number.isFinite(raw.stress)?clamp(raw.stress,0,100):15;
 h.arrears=num(raw.arrears,1e15);h.arrearsSince=Number.isFinite(raw.arrearsSince)?raw.arrearsSince:(h.arrears>0?h.day:-1);h.grace=num(raw.grace);h.load=num(raw.load,1e6);h.cooldown=num(raw.cooldown);h.loanSeq=Math.floor(num(raw.loanSeq,1e9));h.cut=raw.cut===true;
 if(Array.isArray(raw.loans))for(const l of raw.loans.slice(0,12)){if(!l||!LOANS[l.kind])continue;const loan={id:String(l.id||'L'+(++h.loanSeq)).slice(0,24),kind:l.kind,name:String(l.name||LOANS[l.kind].name).slice(0,60),principal:num(l.principal,1e15),balance:num(l.balance,1e15),rate:clamp(num(l.rate),0,.2),payment:num(l.payment,1e15),weeks:Math.floor(num(l.weeks,1000)),paid:Math.floor(num(l.paid,1000)),missed:Math.floor(num(l.missed,100)),fees:num(l.fees,1e15),nextDue:num(l.nextDue),restructured:l.restructured===true,collateral:null};
  if(l.collateral&&['home','car'].includes(l.collateral.kind)&&typeof l.collateral.id==='string')loan.collateral={kind:l.collateral.kind,id:l.collateral.id.slice(0,24)};if(loan.balance+loan.fees>0)h.loans.push(loan);}
 const cats={homes:HOMES,cars:CARS,biz:BUSINESSES};for(const g of Object.keys(cats)){for(const item of cats[g]){const c=raw.cond?.[g]?.[item.id];if(Number.isFinite(c))h.cond[g][item.id]=clamp(c,0,100);if(raw.plans?.[g]?.[item.id]===true)h.plans[g][item.id]=true;}}
 const f=raw.fx||{};h.fx.restUntil=num(f.restUntil);h.fx.pushUntil=num(f.pushUntil);h.fx.leaveUntil=num(f.leaveUntil);h.fx.transit=f.transit===true;h.fx.collections=f.collections===true;h.fx.burnoutSeen=f.burnoutSeen===true;h.fx.deferred=f.deferred===true;h.fx.restDay=Number.isFinite(f.restDay)?f.restDay:-9;
 if(f.slow&&typeof f.slow==='object')for(const b of BUSINESSES)if(Number.isFinite(f.slow[b.id]))h.fx.slow[b.id]=f.slow[b.id];
 if(raw.pending&&typeof raw.pending.type==='string'&&EVENTS[raw.pending.type])h.pending={type:raw.pending.type,id:typeof raw.pending.id==='string'?raw.pending.id.slice(0,24):''};
 if(raw.lastFire&&typeof raw.lastFire==='object')for(const k of Object.keys(EVENTS))if(Number.isFinite(raw.lastFire[k]))h.lastFire[k]=raw.lastFire[k];
 d.house=h;return h;
}
// ---------- lookups
const H=(s=S)=>s.house||(s.house=freshHouse());
const spendTier=(s=S)=>SPEND[H(s).spend]||SPEND.comfortable;
const cond=(g,id,s=S)=>{const v=H(s).cond[g]?.[id];return Number.isFinite(v)?v:100;};
const dailyCar=(s=S)=>CARS.find(c=>c.id===syncLife(s).car)||null;
const onLeave=(s=S)=>H(s).fx.leaveUntil>H(s).day;
const resting=(s=S)=>H(s).fx.restUntil>H(s).day;
const inGrace=(s=S)=>H(s).grace>H(s).day;
const perDay=n=>money(n*DAY)+'/day';
// ---------- household economy (all rates are per second of active play)
function houseExpensesGross(s=S){
 const h=H(s),l=syncLife(s),home=activeHome(s),car=dailyCar(s),t=spendTier(s),inc=incomeRate(s),x=[];
 if(home.id==='room')x.push(['housing','Rent · '+home.name,HR.roomRent]);else x.push(['housing','Property fees · '+home.name,home.cost*HR.homeFees],['housing','Routine upkeep · '+home.name,home.cost*HR.homeUpkeep]);
 x.push(['utilities','Utilities',HR.utilBase+home.comfort*HR.utilPerComfort]);
 x.push(['food','Food & essentials · '+t.name,t.food]);
 if(t.extra)x.push(['lifestyle','Lifestyle spending · '+t.name,Math.max(t.minExtra,inc*t.extra)]);
 for(const o of HOMES)if(l.homes[o.id]&&o.id!==home.id&&o.cost>0)x.push(['second','Second home · '+o.name,o.cost*HR.homeOther]);
 if(car)x.push(['vehicle',(car.id==='bike'?'Bike upkeep':'Running & insurance')+' · '+car.name,car.id==='bike'?HR.bikeRun:car.cost*HR.carRun]);
 for(const c of CARS)if(l.cars[c.id]&&c.id!==l.car&&c.id!=='bike')x.push(['vehicle','Storage & insurance · '+c.name,c.cost*HR.carStored]);
 for(const o of HOMES)if(h.plans.homes[o.id]&&l.homes[o.id]&&o.cost>0)x.push(['plan','Maintenance plan · '+o.name,o.cost*HR.plan]);
 for(const c of CARS)if(h.plans.cars[c.id]&&l.cars[c.id])x.push(['plan','Maintenance plan · '+c.name,Math.max(.004,c.cost*HR.plan)]);
 for(const b of BUSINESSES)if(h.plans.biz[b.id]&&s.business[b.id])x.push(['plan','Service contract · '+b.name,b.cost*s.business[b.id].level*HR.plan]);
 return x;
}
function houseExpenses(s=S){return houseExpensesGross(s).concat(familyExpenses(s));}
function expenseRateFull(s=S){return houseExpenses(s).reduce((n,e)=>n+e[2],0);}
function expenseRate(s=S){return inGrace(s)||s.clicks<10?0:Math.max(0,expenseRateFull(s)-partnerContribution(s));} // costs begin after your first 10 shifts
function cashFlow(s=S){return incomeRate(s)-expenseRate(s);}
function debtTotal(s=S){return H(s).loans.reduce((n,l)=>n+l.balance+l.fees,0);}
function runwayDays(s=S){const f=cashFlow(s);if(f>=0||s.clicks<30)return Infinity;return s.cash/(-f)/DAY;} // pre-routine players live on manual work
function earningPower(s=S){return incomeRate(s)+clickPay(s)*.5;}
function weeklyIncome(s=S){return earningPower(s)*DAY*WEEK;}
function incomeSources(s=S){const x=[['Work routine',automatic(s)*clickPay(s)],['Businesses, net',BUSINESSES.reduce((n,b)=>n+businessDetail(b,s).net,0)],['Rental property, net',propertyRate(s)]];if(s.archiveIncome)x.push(['Legacy trust',s.archiveIncome]);return x;}
// ---------- wellbeing and condition effects (all bounded)
function wellMult(s=S){const h=H(s);let m=1;if(h.stress>=90)m*=.85;else if(h.stress>=70)m*=.92;if(h.health<25)m*=.7;else if(h.health<40)m*=.85;if(h.fx.pushUntil>h.day)m*=1.05;if(h.fx.collections)m*=.85;return Math.max(.55,m);}
function carCondMult(s=S){const c=dailyCar(s);if(!c)return 1;if(H(s).fx.transit)return 0;const v=cond('cars',c.id,s);return v>=50?1:v/50;}
function bizCondMult(b,s=S){const h=H(s);const v=cond('biz',b.id,s);let m=v>=50?1:.7+.3*v/50;if((h.fx.slow[b.id]||0)>h.day)m*=.75;return m;}
function houseComfort(s=S){const h=H(s);let c=spendTier(s).comfort;const v=cond('homes',activeHome(s).id,s);if(v<50)c-=(50-v)/10;if(h.fx.deferred)c-=3;if(h.cut)c-=4;return c;}
function healthLabel(v){return v>=75?'Good':v>=50?'Fair':v>=30?'Poor':'Critical';}
function stressLabel(v){return v<30?'Calm':v<55?'Busy':v<75?'Strained':v<90?'Burning out':'Crisis';}
function condLabel(v){return v>=80?'Good':v>=60?'Worn':v>=40?'Needs attention':v>=20?'Poor':'Failing';}
// ---------- loans
function loanPayment(P,r,n){return r>0?P*r/(1-(1+r)**-n):P/n;}
function loanQuote(kind,amount){const k=LOANS[kind],payment=loanPayment(amount,k.rate,k.weeks);return {kind,principal:amount,rate:k.rate,weeks:k.weeks,payment,total:payment*k.weeks,down:k.down};}
function emergencyLimit(s=S){return clamp(Math.floor(weeklyIncome(s)*1.5/100)*100,1500,250000);}
function loanAffordable(q,s=S){return q.payment<=weeklyIncome(s)*.6+1e-9;}
function loanDue(l){return Math.min(l.payment*(1+l.missed),l.balance)+l.fees;}
function loanById(id){return H().loans.find(l=>l.id===id);}
function takeLoan(kind,amount,collateral=null,name=''){const q=loanQuote(kind,amount),h=H();const l={id:'L'+(++h.loanSeq),kind,name:name||LOANS[kind].name,principal:amount,balance:amount,rate:q.rate,payment:q.payment,weeks:q.weeks,paid:0,missed:0,fees:0,nextDue:h.day+WEEK,restructured:false,collateral};h.loans.push(l);S.cash=num(S.cash+amount);return l;}
function payLoan(l,amount){const want=Math.min(amount,l.balance+l.fees);if(want<=0||!spend(want))return 0;let left=want;const f=Math.min(l.fees,left);l.fees-=f;left-=f;const paidPayments=Math.floor(left/l.payment);l.balance=Math.max(0,l.balance-left);if(l.missed>0)l.missed=Math.max(0,l.missed-Math.max(1,paidPayments));if(l.balance<.005){l.balance=0;l.fees=0;}return want;}
function restructureLoan(l){if(l.restructured)return false;l.balance+=l.fees;l.fees=0;l.rate+=.002;l.weeks=Math.max(4,(l.weeks-l.paid)*2);l.paid=0;l.missed=0;l.payment=loanPayment(l.balance,l.rate,l.weeks);l.restructured=true;l.nextDue=H().day+WEEK;note(`${l.name} restructured: ${money(l.payment)} per game week over ${l.weeks} weeks.`);return true;}
function retireLoans(){const h=H();h.loans=h.loans.filter(l=>{if(l.balance+l.fees>0)return true;note(`${l.name} paid in full.`);return false;});if(!h.loans.some(l=>l.kind==='emergency'&&l.missed>=4))h.fx.collections=false;}
function processLoan(l){
 const interest=l.balance*l.rate;l.balance+=interest;const due=loanDue(l);
 if(S.cash+1e-7>=due){spend(due);const principalPart=due-l.fees;l.fees=0;l.balance=Math.max(0,l.balance-principalPart);l.paid+=1+l.missed;if(l.missed)note(`${l.name}: caught up on ${l.missed} missed payment${l.missed>1?'s':''}.`);l.missed=0;if(l.balance<.005)l.balance=0;}
 else{l.missed++;l.fees+=Math.min(l.payment*.05,l.balance*.01);note(`${l.name}: ${money(l.payment)} payment missed (${l.missed} outstanding).`);
  if(l.missed>=4)queueEvent(l.collateral?'repossess':'collections',l.id);else queueEvent('overdue',l.id);}
 l.nextDue+=WEEK;
}
// ---------- assets: value, sale, repair, plans
function assetBase(kind,id){return kind==='home'?HOMES.find(h=>h.id===id):kind==='car'?CARS.find(c=>c.id===id):BUSINESSES.find(b=>b.id===id);}
function assetGroup(kind){return kind==='home'?'homes':kind==='car'?'cars':'biz';}
function assetValue(kind,id,forced=false,s=S){const a=assetBase(kind,id);if(!a)return 0;const v=cond(assetGroup(kind),id,s);return a.cost*(forced?HR.forced[kind]:HR.sale[kind])*(.6+.4*v/100);}
function repairCost(kind,id,s=S){const a=assetBase(kind,id);if(!a)return 0;const v=cond(assetGroup(kind),id,s);const base=kind==='biz'?a.cost*(s.business[id]?.level||1):a.cost;return Math.ceil((100-v)/100*base*HR.repair[kind]);}
function planCost(kind,id,s=S){const a=assetBase(kind,id);if(!a)return 0;return kind==='biz'?a.cost*(s.business[id]?.level||1)*HR.plan:kind==='car'?Math.max(.004,a.cost*HR.plan):a.cost*HR.plan;}
function repairAsset(kind,id){const h=H(),g=assetGroup(kind),c=repairCost(kind,id);if(!assetBase(kind,id)||cond(g,id)>=100||!spend(c))return false;h.cond[g][id]=100;if(kind==='biz')delete h.fx.slow[id];if(kind==='car')h.fx.transit=false;if(kind==='home'&&id===activeHome().id)h.fx.deferred=false;note(`${assetBase(kind,id).name} repaired for ${money(c)}.`);return true;}
function togglePlan(kind,id){const h=H(),g=assetGroup(kind);if(!assetBase(kind,id))return false;if(h.plans[g][id])delete h.plans[g][id];else h.plans[g][id]=true;return true;}
function collateralLoan(kind,id){return H().loans.find(l=>l.collateral&&l.collateral.kind===kind&&l.collateral.id===id);}
function removeAsset(kind,id){const l=syncLife(S);const a=assetBase(kind,id);if(kind==='home'){delete l.homes[id];if(a.legacy)delete S.items[a.legacy];delete l.layouts[id];if(l.home===id){const next=HOMES.filter(h=>l.homes[h.id]).sort((x,y)=>y.cost-x.cost)[0]||HOMES[0];l.homes.room=true;l.home=next.id;l.room=0;}}
 else{delete l.cars[id];if(a.legacy)delete S.items[a.legacy];if(l.car===id){l.car='';H().fx.transit=false;}}
 delete H().cond[assetGroup(kind)][id];delete H().plans[assetGroup(kind)][id];}
function saleAccounting(kind,id,forced=false){const a=assetBase(kind,id),loan=collateralLoan(kind,id),price=assetValue(kind,id,forced);const fee=forced?Math.min(price*.05,a.cost*.02):0;const owed=loan?loan.balance+loan.fees:0;const toLender=Math.min(owed,Math.max(0,price-fee));const proceeds=Math.max(0,price-fee-toLender);const shortfall=Math.max(0,owed-toLender);return {a,loan,price,fee,owed,toLender,proceeds,shortfall};}
function sellAsset(kind,id,forced=false){
 const acc=saleAccounting(kind,id,forced),l=syncLife(S);if(!acc.a)return null;
 if(kind==='home'&&(id==='room'||!l.homes[id]))return null;if(kind==='car'&&!l.cars[id])return null;
 S.cash=num(S.cash+acc.proceeds);
 if(acc.loan){acc.loan.balance=0;acc.loan.fees=0;const idx=H().loans.indexOf(acc.loan);if(idx>=0)H().loans.splice(idx,1);
  if(acc.shortfall>0){const q=loanQuote('emergency',acc.shortfall);H().loans.push({id:'L'+(++H().loanSeq),kind:'emergency',name:'Deficiency balance · '+acc.a.name,principal:acc.shortfall,balance:acc.shortfall,rate:q.rate,payment:q.payment,weeks:q.weeks,paid:0,missed:0,fees:0,nextDue:H().day+WEEK,restructured:false,collateral:null});}}
 removeAsset(kind,id);retireLoans();note(`${acc.a.name} ${forced?'was surrendered':'sold'} for ${money(acc.price)}.${acc.toLender?' '+money(acc.toLender)+' repaid the lender.':''}${acc.shortfall?' '+money(acc.shortfall)+' remains as an unsecured balance.':''}`);return acc;
}
function grantLife(kind,id){const catalog=kind==='home'?HOMES:CARS,item=catalog.find(i=>i.id===id),l=syncLife(S),owned=kind==='home'?l.homes:l.cars;if(!item||owned[id])return false;owned[id]=true;if(item.legacy)S.items[item.legacy]=true;if(kind==='home'){l.home=id;l.room=0;}else l.car=id;H().cond[assetGroup(kind)][id]=100;return true;}
// ---------- wellbeing actions
function restEvening(){const h=H();if(h.fx.restDay===h.day||paused)return false;h.fx.restDay=h.day;h.stress=clamp(h.stress-15,0,100);note('A quiet evening. Stress −15.');return true;}
function wellnessDay(){const h=H(),c=Math.ceil(Math.max(40,clickPay()*40));if(paused||!spend(c))return false;h.stress=clamp(h.stress-35,0,100);h.health=clamp(h.health+5,0,100);h.fx.restUntil=h.day+1;note(`Wellness day booked for ${money(c)}. Stress −35, health +5, routine rests for a game day.`);return true;}
function medicalCare(){const h=H(),c=Math.ceil(Math.max(120,clickPay()*60));if(paused||!spend(c))return false;h.health=clamp(h.health+30,0,100);note(`Medical check-up for ${money(c)}. Health +30.`);return true;}
function payArrears(){const h=H();if(h.arrears<=0)return false;const p=Math.min(h.arrears,S.cash);if(p<=0||!spend(p))return false;h.arrears=Math.max(0,h.arrears-p);if(h.arrears<.005){h.arrears=0;h.arrearsSince=-1;h.cut=false;note('Overdue household bills cleared.');}else note(`Paid ${money(p)} toward overdue bills.`);return true;}
// ---------- simulation
function houseWork(pay){manualActions++;const h=H();if(h.fx.collections){const l=h.loans.find(x=>x.kind==='emergency'&&x.missed>=4);if(l){const g=Math.min(pay*.15,l.balance+l.fees);if(g>0){S.cash=Math.max(0,S.cash-g);const f=Math.min(l.fees,g);l.fees-=f;l.balance=Math.max(0,l.balance-(g-f));if(l.balance+l.fees<=.005)retireLoans();}}}}
function houseAdvance(seconds,away,gained){
 const h=H();
 if(away){const bill=expenseRate()*seconds,spent=Math.min(gained,bill);S.cash=Math.max(0,S.cash-spent);h.away={seconds,earned:gained,spent,waived:bill-spent,at:Date.now()};return;}
 // continuous household costs
 const due=expenseRate()*seconds;if(due>0){if(S.cash+1e-9>=due)S.cash=Math.max(0,S.cash-due);else{const short=due-S.cash;S.cash=0;h.arrears+=short;if(h.arrearsSince<0)h.arrearsSince=h.day;}}
 // workload: manual and automatic actions are measured identically
 const rate=(manualActions+automatic()*seconds)/seconds;manualActions=0;h.load+=(rate-h.load)*Math.min(1,seconds/30);
 // stress (per second)
 const t=spendTier();let up=0,down=.015*t.recover;
 if(h.load>2)up+=Math.min(.06,(h.load-2)/2*.03);
 if(h.arrears>0)up+=.01;if(h.loans.some(l=>l.missed>0))up+=.01;if(runwayDays()<3)up+=.005;
 if(cond('homes',activeHome().id)<40)up+=.005;if(h.cut)up+=.01;
 if(S.leisure)down+=.03;down+=supportBonus();up+=conflictStress();down+=comfort()*.0003;if(resting())down+=.05;if(h.fx.pushUntil>h.day)down=0;
 h.stress=clamp(h.stress+(up-down)*seconds,0,100);
 // health (per second)
 let hp=0;if(h.stress>=80)hp-=.006;if(h.cut)hp-=.004;if(h.stress<50&&!h.cut)hp+=.004;if(onLeave())hp+=.01;
 h.health=clamp(h.health+hp*seconds,0,100);
 if(h.stress>=75&&!h.fx.burnoutSeen){h.fx.burnoutSeen=true;queueEvent('burnout');}if(h.stress<50)h.fx.burnoutSeen=false;
 if(h.health<20&&!onLeave())queueEvent('leave');
 // day clock
 h.dayClock+=seconds;while(h.dayClock>=DAY){h.dayClock-=DAY;houseDay();}
}
function houseDay(){
 const h=H(),l=syncLife(S),home=activeHome(),car=dailyCar();h.day++;
 // condition decay (per game day)
 for(const o of HOMES){if(!l.homes[o.id]||o.cost===0||h.plans.homes[o.id])continue;h.cond.homes[o.id]=clamp(cond('homes',o.id)-(o.id===home.id?HR.decay.home:HR.decay.homeOther),0,100);}
 for(const c of CARS){if(!l.cars[c.id]||h.plans.cars[c.id])continue;h.cond.cars[c.id]=clamp(cond('cars',c.id)-(c.id===l.car?HR.decay.car:HR.decay.carStored),0,100);}
 for(const b of BUSINESSES){if(!S.business[b.id]||h.plans.biz[b.id])continue;h.cond.biz[b.id]=clamp(cond('biz',b.id)-HR.decay.biz,0,100);}
 // loan payments due this game week
 for(const loan of h.loans.slice())while(loan.nextDue<=h.day&&loan.balance+loan.fees>0)processLoan(loan);retireLoans();
 // overdue household bills
 if(h.arrears>0&&S.cash>=h.arrears){payArrears();}
 if(h.arrears>0){const age=h.day-h.arrearsSince;if(age>=14&&!h.cut){h.cut=true;note('Utilities reduced over unpaid bills. Comfort −4 until you catch up.');}if(age>=7)queueEvent('housing');}
 // condition-driven setbacks (telegraphed, rate limited)
 const rnd=Math.random();
 if(cond('homes',home.id)<30&&home.cost>0&&rnd<.10)queueEvent('repair',home.id);
 else if(car&&cond('cars',car.id)<20&&!h.fx.transit&&rnd<.08)queueEvent('breakdown',car.id);
 else{const b=BUSINESSES.find(b=>S.business[b.id]&&cond('biz',b.id)<25&&!(h.fx.slow[b.id]>h.day));if(b&&rnd<.10)queueEvent('slowdown',b.id);}
 peopleDay();renderNeeded=true;
}
// ---------- events (setbacks). Only ever shown while the player is present.
const EVENT_PRIORITY={repossess:6,collections:5,leave:4,overdue:3,housing:2,burnout:1,repair:0,breakdown:0,slowdown:0};
function queueEvent(type,id=''){const h=H();if(!EVENTS[type])return;const random=EVENT_PRIORITY[type]===0;if(random&&(h.cooldown>h.day||(h.lastFire[type]||-99)>h.day-3))return;if(h.pending){if(EVENT_PRIORITY[type]<=EVENT_PRIORITY[h.pending.type])return;}h.pending={type,id};}
const EVENTS={
 repair:{title:'An unexpected repair',scene:4,cause:id=>`${assetBase('home',id)?.name||'Your home'} is in ${condLabel(cond('homes',id)).toLowerCase()} condition (${Math.round(cond('homes',id))}%). Something finally gave out.`,
  options:id=>[{c:'repair',label:'Repair now · '+money(repairCost('home',id)),cost:repairCost('home',id),desc:'Restores the home to 100%.'},{c:'defer',label:'Live with it for now',desc:'Comfort −3 until the home is repaired. Keeps deteriorating.'}]},
 slowdown:{title:'Equipment trouble',scene:4,cause:id=>`${assetBase('biz',id)?.name||'A business'}'s equipment is at ${Math.round(cond('biz',id))}%. Output is suffering.`,
  options:id=>[{c:'repair',label:'Service everything · '+money(repairCost('biz',id)),cost:repairCost('biz',id),desc:'Restores equipment to 100%.'},{c:'ride',label:'Ride it out',desc:'−25% output at this business for 3 game days.'}]},
 breakdown:{title:'Vehicle breakdown',scene:2,cause:id=>`${assetBase('car',id)?.name||'Your vehicle'} is at ${Math.round(cond('cars',id))}% and would not start this morning.`,
  options:id=>[{c:'repair',label:'Repair · '+money(repairCost('car',id)),cost:repairCost('car',id),desc:'Back on the road at 100%.'},{c:'transit',label:'Take transit for now',desc:'No transport pay bonus until the vehicle is repaired. Running costs continue.'}]},
 burnout:{title:'Burnout warning',scene:1,cause:()=>`Stress is at ${Math.round(H().stress)}. Sustained pressure at work${H().arrears>0||H().loans.some(l=>l.missed)?' and money trouble':''} is catching up with you.`,
  options:()=>[{c:'rest',label:'Rest tonight',desc:'Free. Stress −20 and your routine rests for one game day.'},{c:'wellness',label:'Book a wellness day · '+money(Math.ceil(Math.max(40,clickPay()*40))),cost:Math.ceil(Math.max(40,clickPay()*40)),desc:'Stress −35, health +5, routine rests one game day.'},{c:'push',label:'Push through',desc:'+5% pay for 2 game days, but no stress recovery meanwhile. Health suffers above 80 stress.'}]},
 leave:{title:'Medical leave',scene:5,cause:()=>`Health has dropped to ${Math.round(H().health)}. Your doctor is firm: you need time off. Your routine pauses while you recover; businesses and property keep earning.`,
  options:()=>[{c:'clinic',label:'Private care · '+money(Math.ceil(Math.max(150,clickPay()*150))),cost:Math.ceil(Math.max(150,clickPay()*150)),desc:'Health restored to 60. Two game days of leave.'},{c:'public',label:'Public clinic · free',desc:'Health restored to 45. Four game days of leave.'}]},
 overdue:{title:'Payment overdue',scene:6,cause:id=>{const l=loanById(id);return l?`${l.name}: ${l.missed} missed payment${l.missed>1?'s':''}. ${money(loanDue(l))} would bring it current. ${4-l.missed} more miss${4-l.missed===1?'':'es'} before ${l.collateral?'a repossession review':'collections'}.`:'A loan payment was missed.';},
  options:id=>{const l=loanById(id);return l?[{c:'pay',label:'Pay now · '+money(loanDue(l)),cost:loanDue(l),desc:'Clears missed payments and fees.'},{c:'restructure',label:l.restructured?'Already restructured':'Restructure',disabled:l.restructured,desc:'Double the remaining term at +0.2%/week; fees roll into the balance; missed count resets.'},{c:'later',label:'Handle it later',desc:'Stress keeps rising while it is unpaid.'}]:[{c:'later',label:'Close'}];}},
 collections:{title:'Sent to collections',scene:6,cause:id=>{const l=loanById(id);return l?`${l.name} has ${l.missed} missed payments. 15% of your work pay now goes to the lender until it is repaid.`:'';},
  options:id=>{const l=loanById(id);return l?[{c:'pay',label:'Pay it off · '+money(l.balance+l.fees),cost:l.balance+l.fees,desc:'Ends collections immediately.'},{c:'restructure',label:l.restructured?'Already restructured':'Restructure',disabled:l.restructured,desc:'Longer term, resets missed count, ends the garnish.'},{c:'later',label:'Accept the garnish'}]:[{c:'later',label:'Close'}];}},
 repossess:{title:'Repossession review',scene:6,cause:id=>{const l=loanById(id);if(!l)return '';const acc=saleAccounting(l.collateral.kind,l.collateral.id,true);return `${l.name} has ${l.missed} missed payments. Catch up (${money(loanDue(l))}), restructure, or surrender ${acc.a.name}. Surrender sale ${money(acc.price)} − fees ${money(acc.fee)} → lender ${money(acc.toLender)}${acc.proceeds?', you keep '+money(acc.proceeds):''}${acc.shortfall?', '+money(acc.shortfall)+' remains as an unsecured balance':''}.`;},
  options:id=>{const l=loanById(id);return l?[{c:'pay',label:'Catch up · '+money(loanDue(l)),cost:loanDue(l)},{c:'restructure',label:l.restructured?'Already restructured':'Restructure',disabled:l.restructured},{c:'surrender',label:'Surrender '+assetBase(l.collateral.kind,l.collateral.id).name,desc:'Full accounting shown above. Never happens without your choice.'}]:[{c:'later',label:'Close'}];}},
 housing:{title:'Housing pressure',scene:1,cause:()=>`Household bills are ${money(H().arrears)} overdue (${H().day-H().arrearsSince} game days). ${H().cut?'Utilities are already reduced.':'Utilities are reduced after 14 days.'} Income ${money(incomeRate()*DAY)}/day vs. costs ${money(expenseRate()*DAY)}/day.`,
  options:()=>[{c:'arrears',label:'Pay overdue · '+money(H().arrears),cost:H().arrears},{c:'downsize',label:activeHome().id==='room'?'Already in the rented room':'Move to the rented room',disabled:activeHome().id==='room',desc:'Cuts housing costs to '+money(HR.roomRent*DAY)+'/day. You keep your homes.'},{c:'modest',label:spendTier().name==='Modest'?'Already modest':'Switch to modest spending',disabled:spendTier().name==='Modest'},{c:'later',label:'Later'}]},
};
function showEvent(){const h=H(),p=h.pending;if(!p)return;const ev=EVENTS[p.type];if(!ev){h.pending=null;return;}
 const opts=ev.options(p.id);openModal(ev.title,`<div class="event-scene">${sceneImage(ev.scene,{cls:'scene-thumbnail',lazy:false})}</div><p>${esc(ev.cause(p.id))}</p><div class="event-options">${opts.map(o=>`<button class="btn full ${o.c==='surrender'?'danger':''}" data-action="house-event" data-id="${o.c}" ${o.cost!=null?`data-cost="${o.cost}"`:''} ${o.disabled?'disabled data-locked="true"':''}><span>${o.label}</span>${o.desc?`<small>${o.desc}</small>`:''}</button>`).join('')}</div>`);}
function resolveEvent(choice){const h=H(),p=h.pending;if(!p)return false;const t=p.type,id=p.id;let ok=true;
 if(t==='repair'){if(choice==='repair')ok=repairAsset('home',id);else h.fx.deferred=true;}
 else if(t==='slowdown'){if(choice==='repair')ok=repairAsset('biz',id);else h.fx.slow[id]=h.day+3;}
 else if(t==='breakdown'){if(choice==='repair')ok=repairAsset('car',id);else h.fx.transit=true;}
 else if(t==='burnout'){if(choice==='rest'){h.stress=clamp(h.stress-20,0,100);h.fx.restUntil=h.day+1;}else if(choice==='wellness')ok=wellnessDay();else h.fx.pushUntil=h.day+2;}
 else if(t==='leave'){if(choice==='clinic'){if(!spend(Math.ceil(Math.max(150,clickPay()*150))))return false;h.health=60;h.fx.leaveUntil=h.day+2;}else{h.health=45;h.fx.leaveUntil=h.day+4;}h.stress=clamp(h.stress-20,0,100);note('Medical leave. Your routine pauses while you recover.');}
 else if(t==='overdue'||t==='collections'||t==='repossess'){const l=loanById(id);if(l){if(choice==='pay')ok=payLoan(l,t==='collections'?l.balance+l.fees:loanDue(l))>0;else if(choice==='restructure')ok=restructureLoan(l);else if(choice==='surrender')ok=!!sellAsset(l.collateral.kind,l.collateral.id,true);}
  if(t==='collections'&&choice!=='pay'&&choice!=='restructure')h.fx.collections=true;retireLoans();}
 else if(t==='housing'){if(choice==='arrears')ok=payArrears();else if(choice==='downsize')ok=chooseLife('home','room');else if(choice==='modest')h.spend='modest';}
 if(P_EVENTS[t])ok=resolvePeopleEvent(t,id,choice);
 if(!ok)return false;h.lastFire[t]=h.day;if(EVENT_PRIORITY[t]===0)h.cooldown=h.day+2;h.pending=null;if(typeof document!=='undefined')closeModal();return true;}
function houseTick(){const h=H();if(h.pending&&$('#modal').hidden&&!document.hidden)showEvent();}
// ---------- attention + recommendations
function attentionItems(s=S){const h=H(s),x=[],l=syncLife(s);
 if(h.pending)x.push(['bad','A decision is waiting for you','life','overview']);
 for(const loan of h.loans)if(loan.missed>0)x.push(['bad',`${loan.name}: ${loan.missed} missed payment${loan.missed>1?'s':''}`,'life','budget']);
 if(h.arrears>0)x.push(['bad',`Household bills ${money(h.arrears)} overdue`,'life','budget']);
 if(onLeave(s))x.push(['warn','On medical leave · routine paused','life','overview']);
 if(h.health<40)x.push(['warn','Health is '+healthLabel(h.health).toLowerCase(),'life','overview']);
 if(h.stress>=70)x.push(['warn','Stress: '+stressLabel(h.stress).toLowerCase(),'life','overview']);
 const r=runwayDays(s);if(r<5)x.push(['warn',`Spending exceeds income · ${r<1?'under a day':Math.floor(r)+' game days'} of cash left`,'life','budget']);
 for(const o of HOMES)if(l.homes[o.id]&&o.cost>0&&cond('homes',o.id,s)<40)x.push(['warn',`${o.name}: ${condLabel(cond('homes',o.id,s)).toLowerCase()}`,'life','upkeep']);
 for(const c of CARS)if(l.cars[c.id]&&cond('cars',c.id,s)<40)x.push(['warn',`${c.name}: ${condLabel(cond('cars',c.id,s)).toLowerCase()}`,'life','upkeep']);
 for(const b of BUSINESSES)if(s.business[b.id]&&cond('biz',b.id,s)<40)x.push(['warn',`${b.name} equipment: ${condLabel(cond('biz',b.id,s)).toLowerCase()}`,'life','upkeep']);
 if(h.fx.transit)x.push(['warn','Taking transit · vehicle unrepaired','life','upkeep']);
 peopleAttention(x);return x;}
function recommendations(){const h=H(),x=[];const reserve=expenseRateFull()*DAY*7;
 if(h.pending)x.push('Answer the decision waiting for you.');
 if(h.arrears>0)x.push(S.cash>=h.arrears?'Pay your overdue household bills.':'Raise cash: sell a stored vehicle or second home, or switch to modest spending.');
 for(const l of h.loans)if(l.missed>0)x.push(`Catch up on ${l.name} (${money(loanDue(l))})${l.restructured?'':' or restructure it'}.`);
 if(runwayDays()<7)x.push('Spending exceeds income. Reduce lifestyle spending or grow income before it becomes overdue.');
 if(h.stress>=70)x.push(h.fx.restDay===h.day?'Start a hobby session or book a wellness day to lower stress.':'Take a quiet evening (free) to lower stress.');
 if(h.health<50)x.push('Book a medical check-up before health affects your pay further.');
 const worst=[...HOMES.filter(o=>syncLife(S).homes[o.id]&&o.cost>0).map(o=>['home',o]),...CARS.filter(c=>syncLife(S).cars[c.id]).map(c=>['car',c]),...BUSINESSES.filter(b=>S.business[b.id]).map(b=>['biz',b])].map(([k,a])=>[k,a,cond(assetGroup(k),a.id)]).filter(([,,v])=>v<50).sort((a,b)=>a[2]-b[2])[0];
 if(worst)x.push(`Repair ${worst[1].name} (${money(repairCost(worst[0],worst[1].id))}) or add a maintenance plan.`);
 if(S.cash<reserve&&h.arrears===0)x.push(`Rebuild an emergency reserve: keep about ${money(reserve)} (a week of costs) in cash.`);
 peopleRecommend(x);if(!x.length)x.push('Everything is in order. Keep building.');return x.slice(0,5);}
function attentionTray(){const items=attentionItems();if(!items.length)return '';return `<div class="tray" role="status" aria-label="Needs attention">${items.slice(0,3).map(([lvl,text,tab,view])=>`<button class="tray-item ${lvl}" data-action="house-go" data-id="${view}">${esc(text)}</button>`).join('')}${items.length>3?`<span class="muted small">+${items.length-3} more in Your life</span>`:''}</div>`;}
// ---------- offline summary
function offlineSummary(away,gained){const a=H().away||{seconds:away,earned:gained,spent:0,waived:0};const h=Math.floor(away/3600),m=Math.floor(away%3600/60);const att=attentionItems();
 openModal('Welcome back',`<p>You were away ${h?h+'h ':''}${m}m. Your world kept running.</p><div class="line"><span>Earned while away</span><strong class="mint">+${money(a.earned)}</strong></div><div class="line"><span>Household costs settled</span><strong>−${money(a.spent)}</strong></div>${a.waived>0?`<div class="line"><span>Costs waived (never charged from savings)</span><strong class="muted">${money(a.waived)}</strong></div>`:''}<p class="small muted">Bills, loan payments, wear and stress only move while you play. Nothing came due while you were gone.</p>${att.length?`<div class="eyebrow" style="margin-top:12px">NEEDS ATTENTION</div><ul class="plain">${att.slice(0,4).map(([,t])=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}<div class="actions"><button class="btn primary" data-action="close">Back to it</button></div>`);}
// ---------- UI pieces
function meter(key,label,value,text,cls=''){return `<div class="meter"><div class="line"><span>${label}</span><strong data-live="${key}">${text}</strong></div><div class="track ${cls}"><i data-meter="${key}" style="width:${clamp(value,0,100)}%"></i></div></div>`;}
function houseLive(values){const h=H();values['house-income']=perDay(incomeRate());values['house-exp']=perDay(expenseRate());values['house-net']=(cashFlow()<0?'−':'+')+perDay(Math.abs(cashFlow()));const r=runwayDays();values['house-runway']=r===Infinity?'Sustainable':r<1?'Under a day':Math.floor(r)+' game days';values['house-arrears']=money(h.arrears);values['house-debt']=money(debtTotal());values['health']=Math.round(h.health)+' · '+healthLabel(h.health);values['stress']=Math.round(h.stress)+' · '+stressLabel(h.stress);values['house-cash']=money(S.cash);values['house-day']='Day '+h.day;values['house-exp-s']=money(expenseRate())+'/s';
 if(typeof document==='undefined')return;const meters={health:h.health,stress:h.stress};document.querySelectorAll('[data-meter]').forEach(el=>{const k=el.dataset.meter;let v=meters[k];if(v===undefined&&k.startsWith('cond:')){const [,g,id]=k.split(':');v=cond(g,id);}if(v!==undefined)el.style.width=clamp(v,0,100)+'%';});}
function costPreview(kind,item){const per=kind==='home'?(item.cost===0?HR.roomRent:item.cost*(HR.homeFees+HR.homeUpkeep)):(item.id==='bike'?HR.bikeRun:item.cost*HR.carRun);const inc=incomeRate();const pct=inc>0?Math.round(per/inc*100):null;return `<div class="line small"><span class="muted">${kind==='home'?(item.cost===0?'Rent':'Fees & upkeep'):'Running costs'}</span><span class="mono">${perDay(per)}${pct!==null?' · '+(pct>999?'>999':pct)+'% of income':''}</span></div>`;}
function financeButton(kind,item){const l=syncLife(S),owned=kind==='home'?l.homes:l.cars;if(owned[item.id]||item.cost<1000)return '';const q=loanQuote(kind==='home'?'home':'vehicle',item.cost*(1-LOANS[kind==='home'?'home':'vehicle'].down));return button(`Finance · ${money(item.cost*LOANS[kind==='home'?'home':'vehicle'].down)} down`,'house-finance',kind+':'+item.id,item.cost*LOANS[kind==='home'?'home':'vehicle'].down,false,'ghost');}
function wellbeingPanel(){const h=H();return `<section class="panel"><div class="eyebrow">HOW YOU'RE DOING</div>${meter('health','Health',h.health,Math.round(h.health)+' · '+healthLabel(h.health))}${meter('stress','Stress',h.stress,Math.round(h.stress)+' · '+stressLabel(h.stress),'warn-track')}<p class="small muted">${onLeave()?'On medical leave: routine paused until day '+Math.ceil(h.fx.leaveUntil)+'.':h.stress>=70?'High stress lowers pay. Rest, hobbies and comfort bring it down.':'Steady pace. Sustained pressure above 2 actions/s raises stress.'}</p><div class="actions">${button(h.fx.restDay===h.day?'Rested tonight':'Quiet evening · free','house-rest','',null,h.fx.restDay===h.day)}${button('Life overview','house-go','overview',null,false,'ghost')}</div></section>`;}
function loanCard(l){const cKind=l.collateral?assetBase(l.collateral.kind,l.collateral.id):null;const remaining=Math.max(0,l.weeks-l.paid);return `<article class="card loan"><span class="eyebrow">${LOANS[l.kind].name.toUpperCase()}${cKind?' · SECURED BY '+esc(cKind.name).toUpperCase():' · UNSECURED'}</span><h3>${esc(l.name)}</h3><div class="line"><span>Balance</span><strong>${money(l.balance)}</strong></div>${l.fees?`<div class="line"><span>Late fees</span><strong class="red">${money(l.fees)}</strong></div>`:''}<div class="line"><span>Interest</span><strong>${(l.rate*100).toFixed(2)}% per game week</strong></div><div class="line"><span>Payment</span><strong>${money(l.payment)} every 7 game days</strong></div><div class="line"><span>Next due</span><strong>Day ${l.nextDue} (${Math.max(0,l.nextDue-H().day)} days)</strong></div><div class="line"><span>Paid / scheduled</span><strong>${l.paid} / ${l.weeks} payments</strong></div><div class="line"><span>Remaining at schedule</span><strong>${money(l.payment*remaining+l.fees)}</strong></div>${l.missed?`<div class="kicker">${l.missed} missed payment${l.missed>1?'s':''}. ${money(loanDue(l))} brings it current. ${l.missed>=4?(l.collateral?'Repossession review pending.':'In collections.'):(4-l.missed)+' more before '+(l.collateral?'a repossession review':'collections')+'.'}</div>`:''}<div class="actions">${button('Pay this week · '+money(loanDue(l)),'house-pay',l.id,loanDue(l))}${button('Pay off · '+money(l.balance+l.fees),'house-payoff',l.id,l.balance+l.fees)}${button(l.restructured?'Restructured':'Restructure','house-restructure',l.id,null,l.restructured,'ghost')}</div></article>`;}
function renderHouseOverview(){const h=H(),l=syncLife(S),home=activeHome(),car=dailyCar(),att=attentionItems(),next=h.loans.slice().sort((a,b)=>a.nextDue-b.nextDue)[0];
 const upkeep=[...HOMES.filter(o=>l.homes[o.id]&&o.cost>0).map(o=>['home',o]),...CARS.filter(c=>l.cars[c.id]).map(c=>['car',c]),...BUSINESSES.filter(b=>S.business[b.id]).map(b=>['biz',b])].map(([k,a])=>[k,a,cond(assetGroup(k),a.id)]).sort((a,b)=>a[2]-b[2]).slice(0,3);
 return `<div class="life-overview"><div>${homeExterior(home,car)}<div class="lhc-grid">
 <section class="panel"><div class="eyebrow">HOUSEHOLD</div><div class="line"><span>Income</span><strong data-live="house-income">${perDay(incomeRate())}</strong></div><div class="line"><span>Expenses${inGrace()?' (grace period)':S.clicks<10?' (after 10 shifts)':''}</span><strong data-live="house-exp">${perDay(expenseRate())}</strong></div><div class="line"><span>Net cash flow</span><strong class="${cashFlow()<0?'red':'mint'}" data-live="house-net">${(cashFlow()<0?'−':'+')+perDay(Math.abs(cashFlow()))}</strong></div><div class="line"><span>Runway</span><strong data-live="house-runway">—</strong></div>${inGrace()?`<p class="small muted">New household costs start on day ${h.grace} (${h.grace-h.day} game days).</p>`:''}${button('Budget & debt','house-go','budget',null,false,'full ghost')}</section>
 <section class="panel"><div class="eyebrow">WELLBEING</div>${meter('health','Health',h.health,Math.round(h.health)+' · '+healthLabel(h.health))}${meter('stress','Stress',h.stress,Math.round(h.stress)+' · '+stressLabel(h.stress),'warn-track')}<div class="actions">${button(h.fx.restDay===h.day?'Rested tonight':'Quiet evening · free','house-rest','',null,h.fx.restDay===h.day)}${button('Wellness day · '+money(Math.ceil(Math.max(40,clickPay()*40))),'house-wellness','',Math.ceil(Math.max(40,clickPay()*40)))}${button('Check-up · '+money(Math.ceil(Math.max(120,clickPay()*60))),'house-medical','',Math.ceil(Math.max(120,clickPay()*60)),h.health>=95)}</div></section>
 <section class="panel"><div class="eyebrow">OBLIGATIONS</div><div class="line"><span>Overdue bills</span><strong class="${h.arrears?'red':''}" data-live="house-arrears">${money(h.arrears)}</strong></div><div class="line"><span>Total debt</span><strong data-live="house-debt">${money(debtTotal())}</strong></div><div class="line"><span>Next payment</span><strong>${next?money(loanDue(next))+' · day '+next.nextDue:'None'}</strong></div><div class="line"><span>Billing clock</span><strong data-live="house-day">Day ${h.day}</strong></div>${h.arrears?button('Pay overdue · '+money(h.arrears),'house-arrears','',h.arrears,false,'full'):''}</section>
 <section class="panel"><div class="eyebrow">UPKEEP</div>${upkeep.length?upkeep.map(([k,a,v])=>`<div class="line"><span>${esc(a.name)}</span><strong class="${v<40?'red':v<60?'gold':''}">${Math.round(v)}% · ${condLabel(v)}</strong></div>`).join(''):'<p class="small muted">Nothing to maintain yet.</p>'}${button('Maintenance','house-go','upkeep',null,false,'full ghost')}</section></div></div>
 <aside class="panel"><div class="eyebrow">RECOMMENDED</div><ul class="plain">${recommendations().map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="divider"></div><h3>How this works</h3><p class="small muted">One game day is 60 seconds of play. Costs accrue while you play; loan payments come due every 7 game days. Away time only settles costs out of what you earned, never from savings. Big decisions always wait for you.</p></aside></div>`;}
function renderBudget(){const h=H(),exp=houseExpenses(),inc=incomeSources(),loans=h.loans,limit=emergencyLimit(),amt=clamp(Math.floor(Number(UI.loan)||Math.min(limit,2000)),100,limit),q=loanQuote('emergency',amt);const upcoming=loans.slice().sort((a,b)=>a.nextDue-b.nextDue).slice(0,4);
 return `<div class="life-section-intro"><h2>Know what your life costs.</h2><p>Every figure is per game day (60 seconds of play). ${inGrace()?`<strong>Grace period:</strong> costs are shown but not charged until day ${h.grace}.`:S.clicks<10?'<strong>Costs begin after your first 10 shifts.</strong>':'Costs accrue while you play and are settled from cash.'}</p></div>
 <div class="lhc-grid"><section class="panel"><div class="eyebrow">SPENDING LEVEL</div><div class="spend-tiers">${Object.entries(SPEND).map(([id,t])=>`<button class="spend-tier ${h.spend===id?'current':''}" data-action="house-spend" data-id="${id}" aria-pressed="${h.spend===id}"><strong>${t.name}</strong><small>${money((t.food+(t.extra?Math.max(t.minExtra,incomeRate()*t.extra):0))*DAY)}/day</small><span>${t.desc}</span></button>`).join('')}</div></section>
 <section class="panel"><div class="eyebrow">CASH FLOW</div><div class="line"><span>Income</span><strong data-live="house-income">${perDay(incomeRate())}</strong></div><div class="line"><span>Expenses</span><strong data-live="house-exp">${perDay(expenseRate())}</strong></div><div class="line"><span>Net</span><strong class="${cashFlow()<0?'red':'mint'}" data-live="house-net">${(cashFlow()<0?'−':'+')+perDay(Math.abs(cashFlow()))}</strong></div><div class="line"><span>Runway</span><strong data-live="house-runway">—</strong></div><div class="line"><span>Cash on hand</span><strong data-live="house-cash">${money(S.cash)}</strong></div><div class="line"><span>Overdue bills</span><strong class="${h.arrears?'red':''}" data-live="house-arrears">${money(h.arrears)}</strong></div>${h.arrears?button('Pay overdue · '+money(h.arrears),'house-arrears','',h.arrears,false,'full'):''}<p class="small muted">Manual work is not counted as income here; it is extra on top.</p></section></div>
 <div class="lhc-grid"><section class="panel"><div class="eyebrow">INCOME BY SOURCE</div><table class="budget"><tbody>${inc.map(([n,v])=>`<tr><td>${n}</td><td class="num">${perDay(v)}</td></tr>`).join('')}</tbody></table></section>
 <section class="panel"><div class="eyebrow">EXPENSES BY CATEGORY</div><table class="budget"><tbody>${exp.map(([c,n,v])=>`<tr><td><small class="muted">${c.toUpperCase()}</small><br>${esc(n)}</td><td class="num">${perDay(v)}</td></tr>`).join('')}</tbody></table><p class="small muted">Business operating costs and rental upkeep are already netted out of income above and are never charged twice.</p></section></div>
 <div class="section-title"><h2>Upcoming payments</h2><span>${loans.length} LOAN${loans.length===1?'':'S'}</span></div>${upcoming.length?`<table class="budget"><tbody>${upcoming.map(l=>`<tr><td>${esc(l.name)}${l.missed?` <span class="red">· ${l.missed} missed</span>`:''}</td><td>Day ${l.nextDue}</td><td class="num">${money(loanDue(l))}</td></tr>`).join('')}</tbody></table>`:'<p class="small muted">No loan payments scheduled.</p>'}
 <div class="grid">${loans.map(loanCard).join('')}</div>
 <div class="section-title"><h2>Credit</h2><span>QUOTED PER GAME WEEK</span></div><div class="lhc-grid"><section class="panel"><div class="eyebrow">EMERGENCY LOAN</div><p>${LOANS.emergency.desc}</p><label>Amount (up to ${money(limit)})<input id="loan-amount" type="number" min="100" max="${limit}" step="100" value="${amt}" inputmode="numeric"></label>${chips('loan-amount',[['abs:500','$500'],['abs:1000','$1K'],['abs:'+Math.min(limit,5000),money(Math.min(limit,5000))],['abs:'+limit,'Max']])}<div class="line"><span>Interest</span><strong>${(q.rate*100).toFixed(1)}% per game week</strong></div><div class="line"><span>Payment</span><strong>${money(q.payment)} × ${q.weeks} weeks</strong></div><div class="line"><span>Total repayment</span><strong>${money(q.total)}</strong></div>${button('Review offer','house-loan','',null,h.loans.some(l=>l.kind==='emergency'&&l.missed>=4),'full')}</section><section class="panel"><div class="eyebrow">FINANCING</div><p>${LOANS.vehicle.desc}</p><p>${LOANS.home.desc}</p><p class="small muted">Financing offers appear on each home and vehicle in Properties and Garage. Lenders require the weekly payment to stay under 60% of weekly earning power (${money(weeklyIncome())}).</p></section></div>`;}
function renderUpkeep(){const h=H(),l=syncLife(S),home=activeHome();
 const row=(kind,a,role,decayText)=>{const g=assetGroup(kind),v=cond(g,a.id),plan=!!h.plans[g][a.id],rc=repairCost(kind,a.id),pc=planCost(kind,a.id);const effect=kind==='home'?(v<50?`Comfort −${((50-v)/10).toFixed(1)}`:'No effect yet'):kind==='car'?(a.id===l.car?(v<50?`Transport bonus ×${(v/50).toFixed(2)}`:'No effect yet'):'Stored: no bonus either way'):(v<50?`Output ×${(.7+.3*v/50).toFixed(2)}`:'No effect yet');
  return `<article class="card ${v<40?'attention':''}"><span class="eyebrow">${role}</span><h3>${esc(a.name)}</h3><div class="line"><span>Condition</span><strong class="${v<40?'red':v<60?'gold':''}">${Math.round(v)}% · ${condLabel(v)}</strong></div><div class="track"><i data-meter="cond:${g}:${a.id}" style="width:${v}%"></i></div><div class="line small"><span class="muted">Wear</span><span>${plan?'Covered by plan':decayText}</span></div><div class="line small"><span class="muted">Effect</span><span>${effect}</span></div>${v<20?`<div class="kicker">${kind==='home'?'Risk of an unexpected repair.':kind==='car'?'Risk of a breakdown.':'Risk of an equipment slowdown.'}</div>`:''}<div class="actions">${button(v>=100?'Like new':'Repair · '+money(rc),'house-repair',kind+':'+a.id,rc,v>=100)}${button((plan?'Cancel plan':'Plan')+' · '+perDay(pc),'house-plan',kind+':'+a.id,null,false,'ghost')}${kind!=='biz'&&!(kind==='home'&&a.id==='room')?button('Sell','house-sell',kind+':'+a.id,null,false,'ghost'):''}</div></article>`;};
 const cards=[];for(const o of HOMES)if(l.homes[o.id]&&o.cost>0)cards.push(row('home',o,o.id===home.id?'PRIMARY RESIDENCE':'SECOND HOME',(o.id===home.id?HR.decay.home:HR.decay.homeOther)+'%/day'));
 for(const c of CARS)if(l.cars[c.id])cards.push(row('car',c,c.id===l.car?'DAILY DRIVER':'STORED VEHICLE',(c.id===l.car?HR.decay.car:HR.decay.carStored)+'%/day'));
 for(const b of BUSINESSES)if(S.business[b.id])cards.push(row('biz',b,'BUSINESS EQUIPMENT',HR.decay.biz+'%/day'));
 return `<div class="life-section-intro"><h2>Keep what you own working.</h2><p>Routine upkeep is already in your budget; repairs are extra. A primary residence and daily driver wear fastest, stored vehicles and second homes barely at all. Rental properties keep their own 15% upkeep and are not tracked here.</p></div>${h.fx.transit?`<div class="kicker">You are taking transit. Repair your vehicle to restore the transport bonus.</div>`:''}<div class="grid">${cards.join('')||'<p class="small muted">Nothing to maintain yet. Homes, vehicles and businesses appear here.</p>'}</div>`;}

